  1	/* ============================================================
  2	   views/project-detail-dialogues.js — Project Detail: Dialogues section
  3	   Sub-module of views/project-detail.js.
  4	   Depends on: components.js (UI), utils.js (escapeHtml),
  5	               api-client.js (API)
  6	               This script must be loaded after project-detail-orch.js
  7	               and before project-detail.js in index.html.
  8	
  9	   Exports:
 10	     buildDialogueHTML
 11	     renderDialoguesSection
 12	   ============================================================ */
 13	
 14	/* ----------------------------------------------------------
 15	   Interactive dialogue renderer (WP-006)
 16	   ---------------------------------------------------------- */
 17	
 18	/**
 19	 * Render inline Markdown (bold, italic, inline code) in a plain-text string.
 20	 * Delegates to marked.parseInline() when available; falls back to safe regex
 21	 * substitution (HTML-escaped first) so XSS is impossible on both code paths.
 22	 *
 23	 * @param {string} text - Raw text that may contain **bold**, *italic*, `code`.
 24	 * @returns {string} Safe HTML string.
 25	 */
 26	function _dialogueInlineMarkdown(text) {
 27	  if (typeof marked !== 'undefined' && typeof marked.parseInline === 'function') {
 28	    // Pre-escape HTML before passing to marked so any raw HTML in the input is
 29	    // neutralised before marked processes it. Markdown syntax characters
 30	    // (* _ ` \n) are unaffected by escapeHtml, so bold/italic/code still render
 31	    // correctly. This makes the primary path consistent with the regex fallback.
 32	    return marked.parseInline(escapeHtml(text));
 33	  }
 34	  // Regex fallback: escape HTML first, then apply simple Markdown transforms.
 35	  var safe = escapeHtml(text);
 36	  safe = safe.replace(/\*\*([^*\n]+)\*\*/g, '<strong>$1</strong>');
 37	  safe = safe.replace(/\*([^*\n]+)\*/g, '<em>$1</em>');
 38	  safe = safe.replace(/`([^`\n]+)`/g, '<code>$1</code>');
 39	  return safe;
 40	}
 41	
 42	/**
 43	 * Build HTML for a 'text' dialogue block.
 44	 * Splits content on double newlines to form individual paragraph elements.
 45	 *
 46	 * @param {{type: 'text', content: string}} block
 47	 * @returns {string} HTML string
 48	 */
 49	function _buildDialogueTextBlock(block) {
 50	  var content = block.content || '';
 51	  var paragraphs = content.split(/\n\n+/);
 52	  var pHtml = '';
 53	  var i, para;
 54	  for (i = 0; i < paragraphs.length; i++) {
 55	    para = paragraphs[i].trim();
 56	    if (!para) continue;
 57	    pHtml += '<p>' + _dialogueInlineMarkdown(para) + '</p>';
 58	  }
 59	  return '<div class="dialogue-text">' + pHtml + '</div>';
 60	}
 61	
 62	/**
 63	 * Build HTML for a 'tool-call' dialogue block.
 64	 * Renders as a collapsed-by-default card: toggle button (always visible),
 65	 * ↳ detail lines (always visible, between button and body), and a
 66	 * collapsible body containing the args JSON and optional tool result.
 67	 *
 68	 * @param {{type: 'tool-call', name: string, detailLines: string[], args: *, result: {content: string}|undefined}} block
 69	 * @returns {string} HTML string
 70	 */
 71	function _buildDialogueToolCallBlock(block) {
 72	  var name = block.name || 'unknown';
 73	  var detailLines = block.detailLines || [];
 74	  var args = block.args;
 75	  var result = block.result;
 76	  var i;
 77	
 78	  // Toggle button — always visible, collapsed by default.
 79	  var headerHtml =
 80	    '<button class="dialogue-tool-toggle" aria-expanded="false">' +
 81	      '<span class="dialogue-tool-arrow">\u25b6</span>' +
 82	      'Tool call: ' + escapeHtml(name) +
 83	    '</button>';
 84	
 85	  // ↳ detail lines — always visible, outside the hidden body.
 86	  var detailHtml = '';
 87	  if (detailLines.length) {
 88	    detailHtml += '<div class="dialogue-tool-detail-area">';
 89	    for (i = 0; i < detailLines.length; i++) {
 90	      detailHtml += '<div class="dialogue-tool-detail-line">' + escapeHtml(detailLines[i]) + '</div>';
 91	    }
 92	    detailHtml += '</div>';
 93	  }
 94	
 95	  // Collapsible body: args JSON + optional result (hidden by default).
 96	  var argsJson;
 97	  try {
 98	    argsJson = JSON.stringify(args, null, 2);
 99	  } catch (e) {
100	    argsJson = String(args);

101	  }
102	
103	  var bodyHtml = '<pre class="dialogue-tool-args">' + escapeHtml(argsJson) + '</pre>';
104	
105	  if (result && result.content) {
106	    bodyHtml +=
107	      '<div class="dialogue-tool-result">' +
108	        '<span class="dialogue-tool-result-label">Result:</span>' +
109	        escapeHtml(result.content) +
110	      '</div>';
111	  }
112	
113	  return '<div class="dialogue-tool-call">' +
114	    headerHtml +
115	    detailHtml +
116	    '<div class="dialogue-tool-details" hidden>' + bodyHtml + '</div>' +
117	  '</div>';
118	}
119	
120	/**
121	 * Build HTML for a 'checklist' dialogue block (write_todos invocation).
122	 *
123	 * @param {{type: 'checklist', items: Array<{content: string, status: string, checked: boolean}>}} block
124	 * @returns {string} HTML string
125	 */
126	function _buildDialogueChecklistBlock(block) {
127	  var items = block.items || [];
128	  var listHtml = '';
129	  var i, item, isChecked, checkedAttr, checkedClass;
130	  for (i = 0; i < items.length; i++) {
131	    item = items[i];
132	    isChecked = !!item.checked;
133	    checkedAttr  = isChecked ? ' checked' : '';
134	    checkedClass = isChecked ? ' class="checked"' : '';
135	    listHtml +=
136	      '<li' + checkedClass + '>' +
137	        '<input type="checkbox" disabled' + checkedAttr + '>' +
138	        '<span>' + escapeHtml(item.content || '') + '</span>' +
139	      '</li>';
140	  }
141	  return '<div class="dialogue-checklist"><ul>' + listHtml + '</ul></div>';
142	}
143	
144	/**
145	 * Build HTML for a 'subagent-heading' dialogue block.
146	 *
147	 * @param {{type: 'subagent-heading', label: string}} block
148	 * @returns {string} HTML string
149	 */
150	function _buildDialogueSubagentHeadingBlock(block) {
151	  return '<h3 class="dialogue-subagent-heading">' + escapeHtml(block.label || '') + '</h3>';
152	}
153	
154	/**
155	 * Transform an array of DialogueBlocks into interactive HTML.
156	 *
157	 * - 'text'             → clean paragraphs with inline Markdown support
158	 * - 'tool-call'        → collapsed-by-default card with args/result toggle
159	 * - 'checklist'        → styled list with checkbox indicators
160	 * - 'subagent-heading' → <h3> element
161	 *
162	 * All string values are passed through escapeHtml() for XSS defence.
163	 * All JavaScript follows ES5 patterns (var, function declarations, .then() chains).
164	 *
165	 * @param {Array<{type: string}>} blocks - Array of DialogueBlock objects.
166	 * @returns {string} Safe HTML string ready for assignment to .innerHTML.
167	 */
168	function buildDialogueHTML(blocks) {
169	  if (!blocks || !blocks.length) {
170	    return '<p class="text-muted">No dialogue content.</p>';
171	  }
172	  var html = '';
173	  var i, block;
174	  for (i = 0; i < blocks.length; i++) {
175	    block = blocks[i];
176	    if (block.type === 'text') {
177	      html += _buildDialogueTextBlock(block);
178	    } else if (block.type === 'tool-call') {
179	      html += _buildDialogueToolCallBlock(block);
180	    } else if (block.type === 'checklist') {
181	      html += _buildDialogueChecklistBlock(block);
182	    } else if (block.type === 'subagent-heading') {
183	      html += _buildDialogueSubagentHeadingBlock(block);
184	    }
185	  }
186	  return '<div class="dialogue-interactive">' + html + '</div>';
187	}
188	
189	/* ----------------------------------------------------------
190	   Modal opener
191	   ---------------------------------------------------------- */
192	
193	/**
194	 * Open a full-screen modal showing the rendered content of a single dialogue.
195	 *
196	 * When useChunks is true, fetches structured DialogueBlock[] via
197	 * API.getChunkStructured() and renders via buildDialogueHTML(), including
198	 * an expand/collapse delegated listener for tool-call headers.
199	 *
200	 * When useChunks is false, fetches raw Markdown via API.getDialogueContent()
201	 * and renders via marked.parse() (legacy path — unchanged).
202	 *
203	 * @param {string}  title      - Modal header text (e.g. "WP-003 · developer-r0")
204	 * @param {string}  repo
205	 * @param {string}  slug
206	 * @param {string}  filename
207	 * @param {boolean} useChunks  - true → structured renderer, false → Markdown renderer
208	 */
209	function _openDialogueModal(title, repo, slug, filename, useChunks) {
210	  // Remove any existing dialogue modal
211	  var existing = document.getElementById('dialogue-modal-overlay');
212	  if (existing) existing.remove();
213	
214	  // Build tab bar HTML only when using the structured chunks path.
215	  var tabBarHtml = useChunks
216	    ? '<div class="dialogue-modal-tabs" id="dialogue-modal-tabs">' +
217	        '<button class="dialogue-tab active" id="dialogue-tab-detailed" data-tab="detailed">Detailed</button>' +
218	        '<button class="dialogue-tab" id="dialogue-tab-textonly" data-tab="textonly">Text Only</button>' +
219	      '</div>'
220	    : '';
221	
222	  var modalHtml =
223	    '<div class="dialogue-modal-overlay" id="dialogue-modal-overlay">' +
224	      '<div class="dialogue-modal" role="dialog" aria-modal="true" aria-label="' + escapeHtml(title) + '">' +
225	        '<div class="dialogue-modal-header">' +
226	          '<span class="dialogue-modal-title">' + escapeHtml(title) + '</span>' +
227	          '<button class="dialogue-modal-close" id="dialogue-modal-close" aria-label="Close">\u00d7</button>' +
228	        '</div>' +
229	        tabBarHtml +
230	        '<div class="dialogue-modal-body" id="dialogue-modal-body">' +
231	          '<p class="text-muted">Loading\u2026</p>' +
232	        '</div>' +
233	      '</div>' +
234	    '</div>';
235	
236	  document.body.insertAdjacentHTML('beforeend', modalHtml);
237	
238	  var overlay = document.getElementById('dialogue-modal-overlay');
239	  var bodyEl  = document.getElementById('dialogue-modal-body');
240	
241	  function closeModal() {
242	    if (overlay) overlay.remove();
243	  }
244	
245	  document.getElementById('dialogue-modal-close').addEventListener('click', closeModal);
246	  overlay.addEventListener('click', function (e) {
247	    if (e.target === overlay) closeModal();
248	  });
249	  overlay.addEventListener('keydown', function (e) {
250	    if (e.key === 'Escape') closeModal();

251	  });
252	
253	  if (useChunks) {
254	    // Cache variable for the lazily-fetched Text Only content.
255	    var cachedTextHtml = null;
256	
257	    // Detailed content panel — rendered into bodyEl after the structured fetch.
258	    var detailedPanel = bodyEl;
259	
260	    // Text Only content panel — created lazily on first tab switch.
261	    var textOnlyPanel = document.createElement('div');
262	    textOnlyPanel.id = 'dialogue-panel-textonly';
263	    textOnlyPanel.setAttribute('hidden', '');
264	    textOnlyPanel.className = 'dialogue-modal-body';
265	    textOnlyPanel.style.cssText = detailedPanel.style.cssText;
266	    // Insert the Text Only panel immediately after bodyEl inside the modal.
267	    bodyEl.parentNode.insertBefore(textOnlyPanel, bodyEl.nextSibling);
268	
269	    // Delegated tab-switch click handler on the tab bar.
270	    var tabBar = document.getElementById('dialogue-modal-tabs');
271	    if (tabBar) {
272	      tabBar.addEventListener('click', function (e) {
273	        var btn = e.target;
274	        if (!btn || btn.className.indexOf('dialogue-tab') === -1) return;
275	        var tab = btn.getAttribute('data-tab');
276	        if (!tab) return;
277	
278	        // Update active class on tab buttons.
279	        var tabs = tabBar.querySelectorAll('.dialogue-tab');
280	        for (var i = 0; i < tabs.length; i++) {
281	          if (tabs[i].getAttribute('data-tab') === tab) {
282	            tabs[i].className = 'dialogue-tab active';
283	          } else {
284	            tabs[i].className = 'dialogue-tab';
285	          }
286	        }
287	
288	        if (tab === 'detailed') {
289	          detailedPanel.removeAttribute('hidden');
290	          textOnlyPanel.setAttribute('hidden', '');
291	        } else if (tab === 'textonly') {
292	          detailedPanel.setAttribute('hidden', '');
293	          textOnlyPanel.removeAttribute('hidden');
294	
295	          // Lazy-load: only fetch on first click; use cache on subsequent clicks.
296	          if (cachedTextHtml !== null) {
297	            textOnlyPanel.innerHTML = cachedTextHtml;
298	          } else {
299	            textOnlyPanel.innerHTML = '<p class="text-muted">Loading\u2026</p>';
300	            API.getChunkText(repo, slug, filename).then(function (text) {
301	              var rendered = (typeof marked !== 'undefined' && marked.parse)
302	                ? marked.parse(text)
303	                : '<pre>' + escapeHtml(text) + '</pre>';
304	              cachedTextHtml = '<div class="dialogue-markdown">' + rendered + '</div>';
305	              textOnlyPanel.innerHTML = cachedTextHtml;
306	            }).catch(function (err) {
307	              textOnlyPanel.innerHTML = '<p class="text-danger">Error loading text: ' +
308	                escapeHtml(err.message || String(err)) + '</p>';
309	            });
310	          }
311	        }
312	      });
313	    }
314	
315	    // Structured path: fetch DialogueBlock[] and render with buildDialogueHTML().
316	    API.getChunkStructured(repo, slug, filename).then(function (blocks) {
317	      if (!bodyEl) return;
318	      bodyEl.innerHTML = buildDialogueHTML(blocks);
319	    }).catch(function (err) {
320	      if (!bodyEl) return;
321	      bodyEl.innerHTML = '<p class="text-danger">Error loading dialogue: ' +
322	        escapeHtml(err.message || String(err)) + '</p>';
323	    });
324	
325	    // Delegated click listener for tool-call expand/collapse toggles.
326	    // Registered once on bodyEl; the handler fires after content is loaded
327	    // because user interaction always follows the async render.
328	    bodyEl.addEventListener('click', function (e) {
329	      var btn = e.target.closest('.dialogue-tool-toggle');
330	      if (!btn) return;
331	
332	      var isExpanded = btn.getAttribute('aria-expanded') === 'true';
333	      var detailsEl  = btn.parentNode ? btn.parentNode.querySelector('.dialogue-tool-details') : null;
334	      var arrowEl    = btn.querySelector('.dialogue-tool-arrow');
335	
336	      if (detailsEl) {
337	        if (isExpanded) {
338	          detailsEl.setAttribute('hidden', '');
339	        } else {
340	          detailsEl.removeAttribute('hidden');
341	        }
342	      }
343	      btn.setAttribute('aria-expanded', isExpanded ? 'false' : 'true');
344	      if (arrowEl) {
345	        if (isExpanded) {
346	          arrowEl.classList.remove('expanded');
347	        } else {
348	          arrowEl.classList.add('expanded');
349	        }
350	      }
351	    });
352	  } else {
353	    // Legacy path: fetch raw Markdown and render via marked.parse().
354	    API.getDialogueContent(repo, slug, filename).then(function (md) {
355	      if (!bodyEl) return;
356	      var rendered = (typeof marked !== 'undefined' && marked.parse)
357	        ? marked.parse(md)
358	        : '<pre>' + escapeHtml(md) + '</pre>';
359	      bodyEl.innerHTML = '<div class="dialogue-markdown">' + rendered + '</div>';
360	    }).catch(function (err) {
361	      if (!bodyEl) return;
362	      bodyEl.innerHTML = '<p class="text-danger">Error loading dialogue: ' +
363	        escapeHtml(err.message || String(err)) + '</p>';
364	    });
365	  }
366	}
367	
368	/**
369	 * Render the Dialogues section into `sectionEl`.
370	 * Fetches all chunks and dialogues for the project (no WP filter),
371	 * merges them (chunks take priority over Markdown), groups by
372	 * source + stage, and renders an overview table with expandable
373	 * revision buttons.
374	 *
375	 * @param {HTMLElement} sectionEl  - Placeholder div (#project-dialogues-section)
376	 * @param {string}      repo       - Repository name
377	 * @param {string}      slug       - Project slug
378	 */
379	function renderDialoguesSection(sectionEl, repo, slug) {
380	  if (!sectionEl) return;
381	  sectionEl.innerHTML = '<p class="loading">Loading dialogues\u2026</p>';
382	
383	  Promise.all([
384	    // Fetch all chunks — errors silently swallowed (absent directory is expected).
385	    API.getChunks(repo, slug).catch(function () { return []; }),
386	    // Fetch all dialogues — no wpId filter returns every dialogue for the project.
387	    API.getDialogues(repo, slug),
388	  ]).then(function (results) {
389	    var chunks    = results[0] || [];
390	    var dialogues = results[1] || [];
391	
392	    if (!sectionEl) return;
393	
394	    // Choose data source: chunks take priority over Markdown dialogue files
395	    // (same strategy as the WP detail page — prefer streaming capture format).
396	    var useChunks = chunks.length > 0;
397	    var entries   = useChunks ? chunks : dialogues;
398	
399	    if (!entries || entries.length === 0) {
400	      sectionEl.innerHTML = UI.card('Dialogues',
401	        '<p class="text-muted">No dialogues available for this project.</p>'
402	      );
403	      return;
404	    }
405	
406	    // Group by source (wp_id) + stage.
407	    // Key format: "{wp_id}:{stage}" — stable insertion-order grouping.
408	    var groupMap   = {};
409	    var groupOrder = [];
410	    entries.forEach(function (entry) {
411	      var source = entry.wp_id || 'unknown';
412	      var stage  = entry.stage || 'unknown';
413	      var key    = source + ':' + stage;
414	      if (!groupMap[key]) {
415	        groupMap[key] = { source: source, stage: stage, entries: [] };
416	        groupOrder.push(key);
417	      }
418	      groupMap[key].entries.push(entry);
419	    });
420	
421	    // Build table rows.
422	    var rowsHtml = groupOrder.map(function (key) {
423	      var group   = groupMap[key];
424	      var source  = group.source;
425	      var stage   = group.stage;
426	      var rowEntries = group.entries;
427	
428	      // Source cell: "Project" label for project-level entries, WP-ID badge otherwise.
429	      var sourceHtml;
430	      if (source === 'project') {
431	        sourceHtml = '<span class="dialogue-source-badge dialogue-source-project">Project</span>';
432	      } else {
433	        sourceHtml = '<span class="dialogue-source-badge">' + escapeHtml(source) + '</span>';
434	      }
435	
